selector_to_html = {"a[href=\"#pyskyfire.regen.contour.compute_chamber_volume\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.contour.compute_chamber_volume\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.contour.</span></span><span class=\"sig-name descname\"><span class=\"pre\">compute_chamber_volume</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">xs</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rs</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Compute chamber volume by revolving the contour about the x-axis.</p><p>Integrates <span class=\"math notranslate nohighlight\">\\(\\pi r(x)^2\\)</span> from the left boundary up to the throat\n(the minimum radius).</p><p class=\"rubric\">Notes</p><p>Uses <a class=\"reference external\" href=\"https://numpy.org/doc/stable/reference/generated/numpy.trapezoid.html#numpy.trapezoid\" title=\"(in NumPy v2.5)\"><code class=\"xref py py-func docutils literal notranslate\"><span class=\"pre\">numpy.trapezoid()</span></code></a> for the integral. If the throat occurs at the\nfirst point, returns <code class=\"docutils literal notranslate\"><span class=\"pre\">0.0</span></code>.</p></dd>", "a[href=\"ContourToroidalAerospike.html#pyskyfire.regen.contour.ContourToroidalAerospike\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.contour.ContourToroidalAerospike\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.contour.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ContourToroidalAerospike</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">xs_outer</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rs_outer</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">xs_inner</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rs_inner</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">name</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Axisymmetric contour describing a toroidal-aerospike geometry.</p><p>Defines both the inner and outer wall surfaces, allowing evaluation of\nannular areas and local geometric derivatives.</p><p class=\"rubric\">Notes</p><p>The inner radius is validated to always remain below the outer radius.</p></dd>", "a[href=\"#pyskyfire.regen.contour.generate_contour\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.contour.generate_contour\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.contour.</span></span><span class=\"sig-name descname\"><span class=\"pre\">generate_contour</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">r_t</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">area_ratio</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">r_c</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">L_c</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">V_c</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">eps_c</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">AR_c</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">theta_conv</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">45</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">theta_div</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">15</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">nozzle</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'rao'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">R_1f</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">1.5</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">R_2f</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.5</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">R_3f</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.382</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">length_fraction</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.8</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">angle_input</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'degrees'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">export_tikz</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">False</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Generate a chamber and nozzle contour using four input modes.</p><p>Exactly one of the following input combinations must be provided:</p><p class=\"rubric\">Notes</p><p>In the flow direction, the curvature factors occur in the order\n<code class=\"docutils literal notranslate\"><span class=\"pre\">R_2f</span></code> (chamber fillet), <code class=\"docutils literal notranslate\"><span class=\"pre\">R_1f</span></code> (throat entrance), then <code class=\"docutils literal notranslate\"><span class=\"pre\">R_3f</span></code>\n(throat exit). All three scale the throat radius <code class=\"docutils literal notranslate\"><span class=\"pre\">r_t</span></code>.</p></dd>", "a[href=\"#module-pyskyfire.regen.contour\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.regen.contour<a class=\"headerlink\" href=\"#module-pyskyfire.regen.contour\" title=\"Link to this heading\">\u00b6</a></h1><p>contour.py</p><p>Functinos and methods that together create a thrust chamber contour (combustion chamber + nozzle).</p>", "a[href=\"#module-contents\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Module Contents<a class=\"headerlink\" href=\"#module-contents\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#pyskyfire.regen.contour.generate_contour_internal\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.contour.generate_contour_internal\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.contour.</span></span><span class=\"sig-name descname\"><span class=\"pre\">generate_contour_internal</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">r_c</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">r_t</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">area_ratio</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">L_c</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">theta_conv</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">theta_div</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">nozzle</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">R_1f</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">R_2f</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">R_3f</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">length_fraction</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">export_tikz</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Generate the full nozzle contour coordinates from geometric inputs.</p><p>Builds chamber and nozzle segments (with optional chamber fillet), throat\narcs (entrant/exit), and either a conical or Rao-type nozzle, then joins\nand post-processes them to ensure strictly increasing <code class=\"docutils literal notranslate\"><span class=\"pre\">x</span></code> values.</p></dd>", "a[href=\"Contour.html#pyskyfire.regen.contour.Contour\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.contour.Contour\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.contour.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Contour</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">xs</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rs</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">name</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">chamber_angle</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">nozzle_angle</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Inner hot-gas contour of a bell-type rocket engine.</p><p>Represents the geometric wall line from the start of the chamber to\nthe nozzle exit, providing local areas, slopes, and radii.</p><p class=\"rubric\">Notes</p><p>This class is used by higher-level objects such as\n<code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">CoolingCircuit</span></code> and\n<code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">ThrustChamber</span></code>.</p></dd>", "a[href=\"#pyskyfire.regen.contour.integrate_area\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.contour.integrate_area\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.contour.</span></span><span class=\"sig-name descname\"><span class=\"pre\">integrate_area</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">L_c</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">xs_chamber</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">ys_chamber</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Integrate the area under <code class=\"docutils literal notranslate\"><span class=\"pre\">y(x)</span></code> from <code class=\"docutils literal notranslate\"><span class=\"pre\">x=0</span></code> down to <code class=\"docutils literal notranslate\"><span class=\"pre\">x=-L_c</span></code>.</p></dd>", "a[href=\"#pyskyfire.regen.contour.compute_cutoff_length\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.contour.compute_cutoff_length\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.contour.</span></span><span class=\"sig-name descname\"><span class=\"pre\">compute_cutoff_length</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">V_goal</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">xs_chamber</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">ys_chamber</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Find <code class=\"docutils literal notranslate\"><span class=\"pre\">L_c</span></code> such that the chamber volume from 0 to <code class=\"docutils literal notranslate\"><span class=\"pre\">-L_c</span></code> equals <code class=\"docutils literal notranslate\"><span class=\"pre\">V_goal</span></code>.</p></dd>", "a[href=\"#pyskyfire.regen.contour.get_theta_e_n\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.contour.get_theta_e_n\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.contour.</span></span><span class=\"sig-name descname\"><span class=\"pre\">get_theta_e_n</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">length_fraction</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">epsilon_value</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Interpolate exit and throat angles from tabulated JSON data.</p><p class=\"rubric\">Notes</p><p>The function performs a two-stage interpolation:</p><p>JSON files are read from <code class=\"docutils literal notranslate\"><span class=\"pre\">&lt;this</span> <span class=\"pre\">module&gt;/data/{theta_e,theta_n}.json</span></code>.</p></dd>", "a[href=\"#functions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Functions<a class=\"headerlink\" href=\"#functions\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#classes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
